    /** Enables the save button only if all input fields contain valid values and marks
     *  the offending fields with an error message. */
    private static void validateInput(Button positiveButton, EditText labelInput, EditText secretInput,
                                      EditText periodInput, EditText digitsInput) {
        boolean valid = !TextUtils.isEmpty(labelInput.getText()) && !TextUtils.isEmpty(secretInput.getText());

        if (!validatePositiveNumber(periodInput, R.string.error_empty_period, R.string.error_invalid_period))
            valid = false;

        if (!validatePositiveNumber(digitsInput, R.string.error_empty_digits, R.string.error_invalid_digits))
            valid = false;

        positiveButton.setEnabled(valid);
    }

    /** Checks that the given input contains a number greater than zero and sets an error
     *  message on the input field if it does not. */
    private static boolean validatePositiveNumber(EditText input, int emptyErrorRes, int invalidErrorRes) {
        String value = input.getText().toString().trim();

        if (TextUtils.isEmpty(value)) {
            input.setError(input.getContext().getString(emptyErrorRes));
            return false;
        }

        if (parsePositiveInt(input, -1) <= 0) {
            input.setError(input.getContext().getString(invalidErrorRes));
            return false;
        }

        input.setError(null);
        return true;
    }

    /** Parses the content of the given input field, returning defaultValue if it does not
     *  contain a valid number greater than zero. */
    private static int parsePositiveInt(EditText input, int defaultValue) {
        try {
            int value = Integer.parseInt(input.getText().toString().trim());
            return (value > 0) ? value : defaultValue;
        } catch (NumberFormatException e) {
            return defaultValue;
        }
    }
