211	                validateInput(positiveButton, labelInput, secretInput, periodInput, digitsInput);
212	            }
213	        };
214	
215	        labelInput.addTextChangedListener(watcher);
216	        secretInput.addTextChangedListener(watcher);
217	        periodInput.addTextChangedListener(watcher);
218	        digitsInput.addTextChangedListener(watcher);
219	
220	        validateInput(positiveButton, labelInput, secretInput, periodInput, digitsInput);
221	    }
