223	    /** Enables the save button only if all input fields contain valid values and marks
224	     *  the offending fields with an error message. */
225	    private static void validateInput(Button positiveButton, EditText labelInput, EditText secretInput,
226	                                      EditText periodInput, EditText digitsInput) {
227	        boolean valid = !TextUtils.isEmpty(labelInput.getText()) && !TextUtils.isEmpty(secretInput.getText());
228	
229	        if (!validatePositiveNumber(periodInput, R.string.error_empty_period, R.string.error_invalid_period))
230	            valid = false;
231	
232	        if (!validatePositiveNumber(digitsInput, R.string.error_empty_digits, R.string.error_invalid_digits))
233	            valid = false;
234	
235	        positiveButton.setEnabled(valid);
236	    }
