238	    /** Checks that the given input contains a number greater than zero and sets an error
239	     *  message on the input field if it does not. */
240	    private static boolean validatePositiveNumber(EditText input, int emptyErrorRes, int invalidErrorRes) {
241	        String value = input.getText().toString().trim();
242	
243	        if (TextUtils.isEmpty(value)) {
244	            input.setError(input.getContext().getString(emptyErrorRes));
245	            return false;
246	        }
247	
248	        if (parsePositiveInt(input, -1) <= 0) {
249	            input.setError(input.getContext().getString(invalidErrorRes));
250	            return false;
251	        }
252	
253	        input.setError(null);
254	        return true;
255	    }
256	
257	    /** Parses the content of the given input field, returning defaultValue if it does not
258	     *  contain a valid number greater than zero. */
259	    private static int parsePositiveInt(EditText input, int defaultValue) {
260	        try {
261	            int value = Integer.parseInt(input.getText().toString().trim());
262	            return (value > 0) ? value : defaultValue;
263	        } catch (NumberFormatException e) {
264	            return defaultValue;
265	        }
266	    }
